class ErrorResponse(BaseModel):
    """
    Standard error envelope for JSON APIs. `success` is always false; `error` is a stable
    code for clients, while `message` is safe to show to users. Use `error_id` when
    correlating with server logs; `field_errors` carries validation details when present.

    """

    success: Success1
    error: str = Field(
        ...,
        description="Machine-oriented error code or short error type (e.g. validation_error, GOOGLE_OAUTH_FAILED).",
    )
    message: str | None = Field(None, description="Human-readable message when provided.")
    error_id: str | None = Field(
        None,
        description="Unique error tracking ID from SecureErrorHandler (short UUID prefix) for server-side log correlation.",
    )
    retryable: bool | None = Field(
        None,
        description="True when the client may retry (e.g. transient Google token refresh / network failures, 503-style cases).",
    )
    field_errors: dict[str, str | list[str]] | None = Field(
        None,
        description="Per-field validation messages from SecureErrorHandler (sanitized string per field); some validators may emit multiple messages per field as an array.\n",
    )
    validation_errors: dict[str, Any] | None = Field(
        None,
        description="Optional alternate validation map when included via secure error additional_info. Values are usually strings or lists of strings (same shape as field_errors); additionalProperties stays open for legacy or nested payloads from some validators.\n",
    )
    details: str | dict[str, Any] | None = Field(
        None,
        description="Additional context as plain text or structured map (e.g. legacy Marshmallow validate_request).",
    )
    status_code: int | None = Field(
        None,
        description="Optional HTTP status echoed in the JSON body; the authoritative status is the response status line.",
    )
    retry_after: int | None = Field(
        None,
        description="Suggested delay in seconds before retrying (e.g. rate limit responses).",
    )
    allowed_types: list[str] | None = Field(
        None, description="Allowed values hint (e.g. some file upload error responses)."
    )


